_STABILITY_SUM_SCHEMA = "climate-grid/ws-v1"
_STABILITY_SUM_ITEM_KEYS = ("name", "result")
_STABILITY_SUM_ROW_KEYS = (
    "scenario",
    "count",
    "reversals",
    "longest_run",
    "stable_rate",
    "level",
)
_STABILITY_LEVELS = ("stable", "low", "medium", "high")


def _validate_rank_change_stability(
    result: Any, *, where: str = "result"
) -> tuple[list[str], list[str], list]:
    """Validate a complete :func:`rank_change_stability` result.

    Returns the window names, the scenario order and the ``data`` rows.
    """
    if not isinstance(result, dict):
        raise TypeError(f"{where} must be a dict")
    if tuple(result.keys()) != _REGION_WINDOW_RANK_CHANGE_STABILITY_RESULT_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys schema, windows, "
            "scenarios, data in order"
        )

    schema = result["schema"]
    if not isinstance(schema, str):
        raise TypeError(f"{where}.schema must be a str")
    if schema != _REGION_WINDOW_RANK_CHANGE_STABILITY_SCHEMA:
        raise ValueError(
            f"{where}.schema must be "
            f"{_REGION_WINDOW_RANK_CHANGE_STABILITY_SCHEMA!r}"
        )

    windows = _validate_string_list(
        result["windows"], f"{where}.windows", minimum=2
    )
    scenarios = _validate_string_list(result["scenarios"], f"{where}.scenarios")

    data = result["data"]
    if not isinstance(data, list):
        raise TypeError(f"{where}.data must be a list")
    if len(data) != len(scenarios):
        raise ValueError(
            f"{where}.data must have {len(scenarios)} rows (one per "
            "scenario, in scenario order)"
        )

    max_count = len(windows) - 1
    for index, row in enumerate(data):
        row_where = f"{where}.data[{index}]"
        if not isinstance(row, dict):
            raise TypeError(f"{row_where} must be a dict")
        if tuple(row.keys()) != _STABILITY_SUM_ROW_KEYS:
            raise ValueError(
                f"{row_where} must have exactly the keys scenario, count, "
                "reversals, longest_run, stable_rate, level in order"

    if tuple(row.keys()) != _STABILITY_SUM_ROW_KEYS:
        raise ValueError(
            f"{row_where} must have exactly the keys scenario, count, "
            "reversals, longest_run, stable_rate, level in order"
        )

    scenario = row["scenario"]
    if not isinstance(scenario, str):
        raise TypeError(f"{row_where}.scenario must be a str")
    if scenario != scenarios[index]:
        raise ValueError(
            f"{row_where}.scenario must be {scenarios[index]!r} for its "
            "scenario-order position"
        )

    count = row["count"]
    if not isinstance(count, int) or isinstance(count, bool):
        raise TypeError(f"{row_where}.count must be a non-bool int")
    if not 0 <= count <= max_count:
        raise ValueError(
            f"{row_where}.count must be between 0 and the number of "
            "adjacent window pairs"
        )

    reversals = row["reversals"]
    longest_run = row["longest_run"]
    stable_rate = row["stable_rate"]
    level = row["level"]
    members = (reversals, longest_run, stable_rate, level)
    if any(member is None for member in members):
        if not all(member is None for member in members):
            raise ValueError(
                f"{row_where}: reversals, longest_run, stable_rate and "
                "level must be all None or all present"
            )
        if count != 0:
            raise ValueError(
                f"{row_where}: reversals, longest_run, stable_rate and "
                "level must be present when count is positive"
            )
        continue

    if count < 1:
        raise ValueError(
            f"{row_where}: reversals, longest_run, stable_rate and "
            "level must be None when count is zero"
        )
    if not isinstance(reversals, int) or isinstance(reversals, bool):
        raise TypeError(f"{row_where}.reversals must be a non-bool int")
    if not 0 <= reversals <= max(count - 1, 0):
        raise ValueError(
            f"{row_where}.reversals must be between 0 and "
            f"{row_where}.count - 1"
        )
    if not isinstance(longest_run, int) or isinstance(longest_run, bool):
        raise TypeError(f"{row_where}.longest_run must be a non-bool int")
    if not 0 <= longest_run <= count:
        raise ValueError(
            f"{row_where}.longest_run must be between 0 and "
            f"{row_where}.count"
        )
    _validate_number(stable_rate, f"{row_where}.stable_rate", nullable=False)
    if not 0 <= stable_rate <= 1:
        raise ValueError(
            f"{row_where}.stable_rate must be between 0 and 1"
        )
    if not isinstance(level, str):
        raise TypeError(f"{row_where}.level must be a str")
    if level not in _STABILITY_LEVELS:
        raise ValueError(
            f"{row_where}.level must be one of stable, low, medium, high"
        )

return windows, scenarios, data

def _validate_layer_sum_result(
    summary: Any, *, where: str = "summary"
) -> tuple[str, list[str], list[str], list[str], list]:
    if not isinstance(summary, dict):
        raise TypeError(f"{where} must be a dict")
    if tuple(summary.keys()) != _LAYER_SUM_RESULT_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys schema, layers, "
            "reference, scenarios, elements, drivers, data in order"
        )

    schema = summary["schema"]
    if not isinstance(schema, str):
        raise TypeError(f"{where}.schema must be a str")
    if schema != _LAYER_SUM_SCHEMA:
        raise ValueError(f"{where}.schema must be {_LAYER_SUM_SCHEMA!r}")

    layers = summary["layers"]
    if not isinstance(layers, list):
        raise TypeError(f"{where}.layers must be a list")
    if len(layers) == 0:
        raise ValueError(f"{where}.layers must be non-empty")
    seen_pairs: set[tuple[str, str]] = set()
    for index, layer in enumerate(layers):
        layer_where = f"{where}.layers[{index}]"
        if not isinstance(layer, dict):
            raise TypeError(f"{layer_where} must be a dict")
        if tuple(layer.keys()) != _LAYER_SUM_LAYER_KEYS:
            raise ValueError(
                f"{layer_where} must have exactly the keys period, region "
                "in order"
            )
        period = layer["period"]
        region = layer["region"]
        if not isinstance(period, str):
            raise TypeError(f"{layer_where}.period must be a str")
        if period == "":
            raise ValueError(f"{layer_where}.period must be non-empty")
        if not isinstance(region, str):
            raise TypeError(f"{layer_where}.region must be a str")
        if region == "":
            raise ValueError(f"{layer_where}.region must be non-empty")
        if (period, region) in seen_pairs:
            raise ValueError(
                f"duplicate period/region pair in {where}: "
                f"{(period, region)!r}"
            )
        seen_pairs.add((period, region))

    reference = summary["reference"]
    if not isinstance(reference, str):
        raise TypeError(f"{where}.reference must be a str")
    if reference == "":
        raise ValueError(f"{where}.reference must be non-empty")

    scenarios = _validate_string_list(
        summary["scenarios"], f"{where}.scenarios"
    )
    elements = _validate_string_list(
        summary["elements"], f"{where}.elements"
    )
    drivers = _validate_string_list(summary["drivers"], f"{where}.drivers")

    data = summary["data"]
    if not isinstance(data, list):
        raise TypeError(f"{where}.data must be a list")
    expected_rows = len(scenarios) * len(elements) * len(drivers)
    if len(data) != expected_rows:
        raise ValueError(
            f"{where}.data must have {expected_rows} rows (one per "
            "scenario/element/driver combination, in "
            "scenario-then-element-then-driver order)"
        )

    row_index = 0
    for scenario in scenarios:
        for element in elements:
            for driver in drivers:
                row_where = f"{where}.data[{row_index}]"
                row = data[row_index]
                if not isinstance(row, dict):
                    raise TypeError(f"{row_where} must be a dict")
                if tuple(row.keys()) != _LAYER_SUM_RESULT_ROW_KEYS:
                    raise ValueError(
                        f"{row_where} must have exactly the keys scenario, "
                        "element, driver, count, mean, min, max, uncertainty "
                        "in order"
                    )

                row_scenario = row["scenario"]
                if not isinstance(row_scenario, str):
                    raise TypeError(f"{row_where}.scenario must be a str")
                if row_scenario != scenario:
                    raise ValueError(
                        f"{row_where}.scenario must be {scenario!r} for its "
                        "scenario-then-element-then-driver position"
                    )
                row_element = row["element"]
                if not isinstance(row_element, str):
                    raise TypeError(f"{row_where}.element must be a str")
                if row_element != element:
                    raise ValueError(
                        f"{row_where}.element must be {element!r} for its "
                        "scenario-then-element-then-driver position"
                    )
                row_driver = row["driver"]
                if not isinstance(row_driver, str):
                    raise TypeError(f"{row_where}.driver must be a str")
                if row_driver != driver:
                    raise ValueError(
                        f"{row_where}.driver must be {driver!r} for its "
                        "scenario-then-element-then-driver position"
                    )

                count = row["count"]
                if not isinstance(count, int) or isinstance(count, bool):
                    raise TypeError(f"{row_where}.count must be a non-bool int")
                if count < 0:
                    raise ValueError(f"{row_where}.count must be non-negative")

                mean = row["mean"]
                minimum = row["min"]
                maximum = row["max"]
                uncertainty = row["uncertainty"]
                _validate_number(mean, f"{row_where}.mean", nullable=True)
                _validate_number(minimum, f"{row_where}.min", nullable=True)
                _validate_number(maximum, f"{row_where}.max", nullable=True)
                _validate_number(
                    uncertainty, f"{row_where}.uncertainty", nullable=True
                )
                if (
                    (mean is None)
                    != (minimum is None)
                    or (mean is None) != (maximum is None)
                    or (mean is None) != (uncertainty is None)
                ):
                    raise ValueError(
                        f"{row_where}: mean, min, max and uncertainty must be "
                        "all None or all present"
                    )
                if count == 0 and mean is not None:
                    raise ValueError(
                        f"{row_where}: mean, min, max and uncertainty must be "
                        "all None when count is 0"
                    )
                if uncertainty is not None and uncertainty < 0:
                    raise ValueError(
                        f"{row_where}.uncertainty must be non-negative"
                    )

                row_index += 1

    return reference, scenarios, elements, drivers, data


